// Verify the dispatcher's HMAC-SHA256 signature.
// Signed string: `${x-sf-timestamp}.${rawBody}` where rawBody is the exact
// JSON bytes the dispatcher POSTed. Secret comes from $env.N8N_WEBHOOK_SECRET
// (same value as Render AUTOMATION_WEBHOOK_SECRET). Never hardcode it here.
// Timestamp tolerance: +/-300 seconds (replay protection).
//
// Raw body source (in priority order):
//   1. binary.data.data (base64) — present when the Webhook node's Raw Body
//      option is ON (required). If this is missing, Raw Body got turned off.
//   2. a string json.body.
//   3. JSON.stringify(json.body) — last resort; can fail verification if key
//      order differs from what the dispatcher sent, which is exactly why
//      Raw Body must be ON.
// Also parses the event once and passes it on, so later nodes do not depend
// on how n8n exposed the body.
const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers || {};
const signature = headers['x-sf-signature'] || '';
const timestamp = headers['x-sf-timestamp'] || '';

let rawBody = '';
let rawBodySource = 'none';
const bin = item.binary && item.binary.data && item.binary.data.data;
if (typeof bin === 'string' && bin.length > 0) {
  rawBody = Buffer.from(bin, 'base64').toString('utf8');
  rawBodySource = 'binary';
} else if (typeof item.json.body === 'string') {
  rawBody = item.json.body;
  rawBodySource = 'string-body';
} else if (item.json.body) {
  rawBody = JSON.stringify(item.json.body);
  rawBodySource = 'stringified-body';
}

let event = null;
try {
  event = rawBody ? JSON.parse(rawBody) : (item.json.body || null);
} catch (e) {
  event = null;
}

let verified = false;
let reason = '';
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) {
  reason = 'N8N_WEBHOOK_SECRET is not set in the n8n environment';
} else if (!signature || !timestamp) {
  reason = 'missing x-sf-signature or x-sf-timestamp header';
} else if (!/^\d+$/.test(timestamp)) {
  reason = 'x-sf-timestamp is not numeric';
} else if (Math.abs(Math.floor(Date.now() / 1000) - parseInt(timestamp, 10)) > 300) {
  reason = 'timestamp outside +/-300s tolerance (replay protection)';
} else if (!rawBody) {
  reason = 'empty body — is Raw Body enabled on the Webhook node?';
} else {
  const expected = crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.${rawBody}`)
    .digest('hex');
  // Constant-time compare; guard the length check first (timingSafeEqual throws on mismatch).
  const a = Buffer.from(signature, 'utf8');
  const b = Buffer.from(expected, 'utf8');
  verified = a.length === b.length && crypto.timingSafeEqual(a, b);
  if (!verified) reason = 'signature mismatch';
}

return [{ json: { verified, reason, rawBodySource, event } }];

// Validate the event shape and drop duplicates (idempotency).
// Required: event_id (or id), event_type, workspace_id.
// Known event types are the outbox types from apps/api/src/lib/outbox.ts and
// supabase/migrations/0003_phase2_support_platform.sql.
// Duplicates are remembered in workflow static data, keyed by event_id,
// for 24 hours (max 5000 entries, oldest pruned first). Static data is only
// persisted for ACTIVE (production) executions — manual test runs do not
// save seen ids, so re-running a test can legitimately re-deliver an event.
// No customer data is logged here: only ids and the event type.
const KNOWN_EVENT_TYPES = [
  'customer.message.created',
  'conversation.created',
  'ticket.created',
  'ticket.priority.changed',
  'ticket.assigned',
  'ticket.resolved',
];

const input = $input.first().json;
const rawEvent = input.event || {};
const eventId = rawEvent.event_id || rawEvent.id || null;
const eventType = rawEvent.event_type || null;
const workspaceId = rawEvent.workspace_id || null;

let ok = true;
let reason = '';
if (!eventId) { ok = false; reason = 'missing event_id'; }
else if (!eventType) { ok = false; reason = 'missing event_type'; }
else if (!KNOWN_EVENT_TYPES.includes(eventType)) { ok = false; reason = `unknown event_type: ${eventType}`; }
else if (!workspaceId) { ok = false; reason = 'missing workspace_id'; }

let duplicate = false;
if (ok) {
  const staticData = $getWorkflowStaticData('global');
  staticData.seen = staticData.seen || {};
  const now = Date.now();
  const DAY_MS = 24 * 60 * 60 * 1000;
  // Prune entries older than 24 h.
  for (const key of Object.keys(staticData.seen)) {
    if (now - staticData.seen[key] > DAY_MS) delete staticData.seen[key];
  }
  // Cap the store: drop the oldest entries if it grows past 5000.
  const keys = Object.keys(staticData.seen);
  if (keys.length > 5000) {
    keys
      .sort((a, b) => staticData.seen[a] - staticData.seen[b])
      .slice(0, keys.length - 5000)
      .forEach((k) => delete staticData.seen[k]);
  }
  if (staticData.seen[eventId]) {
    duplicate = true;
  } else {
    staticData.seen[eventId] = now;
  }
}

// Normalise the event: always expose event_id, keep the dispatcher's fields.
const event = { ...rawEvent, event_id: eventId };
return [{ json: { ok, duplicate, reason, event_type: eventType, event } }];

// Sign the outbound call to the API with the same shared secret.
// Signed string: `${timestamp}.${rawBody}` where rawBody is exactly the
// JSON string the HTTP Request node will send (JSON.stringify of the same
// event object), so the API's verification over the bytes it receives
// matches. The API verifies this signature on POST /api/automation/process-event.
const crypto = require('crypto');

const event = $input.first().json.event;
const timestamp = Math.floor(Date.now() / 1000).toString();
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('N8N_WEBHOOK_SECRET is not set in the n8n environment');
}
const rawBody = JSON.stringify(event);
const signature = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

return [{ json: { event, signature, timestamp } }];
